"use client";

import { memo, useRef, type ComponentProps } from "react";
import { cn } from "cn";
import { AspectRatio } from "./aspect-ratio";
import { DitherBackground, type DitherBackgroundProps } from "../shader/dither-background";

type DitheredLogoProps = Omit<ComponentProps<"div">, "color" | "children"> &
  Pick<DitherBackgroundProps, "color" | "backgroundColor" | "pixelSize" | "speed"> & {
    src?: string;
    alt?: string;
    ratio?: number;
  };

export const DitheredLogo = memo(function DitheredLogo({
  src = "/logo.svg",
  alt = "Hangry UI",
  ratio = 2,
  color,
  backgroundColor,
  pixelSize,
  speed,
  className,
  ...props
}: DitheredLogoProps = {}) {
  const interactionRef = useRef<HTMLDivElement>(null);
  const mask = `url(${JSON.stringify(src)})`;
  return (
    <AspectRatio
      {...props}
      ref={interactionRef}
      ratio={Number.isFinite(ratio) && ratio > 0 ? ratio : 2}
      data-slot="dithered-logo"
      role={alt ? "img" : undefined}
      aria-label={alt || undefined}
      aria-hidden={alt ? undefined : true}
      className={cn("w-full max-w-lg", className)}
    >
      <div
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 isolate"
        style={{
          backgroundImage: color ? undefined : mask,
          backgroundSize: "contain",
          backgroundRepeat: "no-repeat",
          backgroundPosition: "center",
          maskImage: mask,
          maskSize: "contain",
          maskRepeat: "no-repeat",
          maskPosition: "center",
          WebkitMaskImage: mask,
          WebkitMaskSize: "contain",
          WebkitMaskRepeat: "no-repeat",
          WebkitMaskPosition: "center",
        }}
      >
        <DitherBackground
          interactive
          themeAware={false}
          interactionRef={interactionRef}
          color={color ?? [1, 1, 1]}
          backgroundColor={backgroundColor}
          pixelSize={pixelSize}
          speed={speed}
          className={cn("h-full min-h-0 w-full border-0", !color && "mix-blend-multiply")}
        />
      </div>
    </AspectRatio>
  );
});

import { memo, type ComponentProps, type CSSProperties } from "react";
import { cn } from "cn";

interface AspectRatioProps extends ComponentProps<"div"> {
  ratio?: number;
}

export const AspectRatio = memo(function AspectRatio({
  ratio = 1,
  className,
  style,
  ...props
}: AspectRatioProps = {}) {
  return (
    <div
      data-slot="aspect-ratio"
      style={{ "--ratio": ratio, ...style } as CSSProperties}
      className={cn("relative aspect-(--ratio)", className)}
      {...props}
    />
  );
});

"use client";

import { memo, useEffect, useRef, type ComponentProps, type RefObject } from "react";
import { useReducedMotion, useSpring } from "motion/react";
import { createShaderRenderer } from "./shader-renderer.shared";
import { cn } from "cn";
import ditherShader from "./dither-background.wgsl";

type Color = readonly [number, number, number];
const defaultColor: Color = [0.02, 0.86, 0.5];
const defaultBackground: Color = [0.02, 0.04, 0.035];

export interface DitherBackgroundProps extends Omit<ComponentProps<"div">, "color"> {
  color?: Color;
  themeAware?: boolean;
  backgroundColor?: Color;
  pixelSize?: number;
  speed?: number;
  interactive?: boolean;
  interactionRef?: RefObject<HTMLElement | null>;
}

export const DitherBackground = memo(function DitherBackground({
  color = defaultColor,
  themeAware = true,
  backgroundColor = defaultBackground,
  pixelSize = 3,
  speed = 0.4,
  interactive = true,
  interactionRef,
  children,
  className,
  ...props
}: DitherBackgroundProps = {}) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const reducedMotion = useReducedMotion();
  const hoverStrength = useSpring(0, { stiffness: 180, damping: 24 });
  const pixels = Number.isFinite(pixelSize) ? Math.max(1, pixelSize) : 3;
  const rate = Number.isFinite(speed) ? Math.max(0, speed) : 0.4;
  const [r, g, b] = color.map((channel) =>
    Math.min(1, Math.max(0, Number.isFinite(channel) ? channel : 0)),
  );
  const [br, bg, bb] = backgroundColor.map((channel) =>
    Math.min(1, Math.max(0, Number.isFinite(channel) ? channel : 0)),
  );

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    let pointer = [0.5, 0.5, 0, 0];
    let ripple = [0.5, 0.5, 0, 0];
    let rippleStarted = -Infinity;
    const host = interactionRef?.current ?? canvas.parentElement?.parentElement;
    const trackPointer = (event: PointerEvent) => {
      if (!interactive || reducedMotion || event.pointerType === "touch" || !host) return;
      const bounds = host.getBoundingClientRect();
      if (!bounds.width || !bounds.height) return;
      pointer = [
        (event.clientX - bounds.left) / bounds.width,
        (event.clientY - bounds.top) / bounds.height,
        1,
        0,
      ];
      hoverStrength.set(1);
    };
    const clearPointer = () => {
      hoverStrength.set(0);
    };
    const triggerRipple = (event: PointerEvent) => {
      if (!interactive || reducedMotion || !host || event.button !== 0) return;
      const bounds = host.getBoundingClientRect();
      if (!bounds.width || !bounds.height) return;
      ripple = [
        (event.clientX - bounds.left) / bounds.width,
        (event.clientY - bounds.top) / bounds.height,
        0,
        1,
      ];
      rippleStarted = performance.now();
      if (event.pointerType !== "mouse") clearPointer();
    };
    host?.addEventListener("pointermove", trackPointer);
    host?.addEventListener("pointerleave", clearPointer);
    host?.addEventListener("pointercancel", clearPointer);
    host?.addEventListener("pointerup", triggerRipple);

    const cleanup = () => {
      host?.removeEventListener("pointermove", trackPointer);
      host?.removeEventListener("pointerleave", clearPointer);
      host?.removeEventListener("pointercancel", clearPointer);
      host?.removeEventListener("pointerup", triggerRipple);
      hoverStrength.jump(0);
      renderer.dispose();
    };

    const renderer = createShaderRenderer(canvas, ditherShader, {
      label: "dither-background",
      themeAware,
      fps: 30,
      animated: !reducedMotion && (rate > 0 || interactive),
      uniforms: (time, size) => {
        pointer[2] = reducedMotion ? 0 : hoverStrength.get();
        const age = (performance.now() - rippleStarted) / 1000;
        ripple[2] = Number.isFinite(age) ? age : 0;
        ripple[3] = !reducedMotion && age < 0.675 ? 1 : 0;
        return {
          cfg: {
            metrics: [size[0], size[1], pixels, time * rate],
            pointer,
            ripple,
            foreground: [r, g, b, 1],
            background: [br, bg, bb, 1],
          },
        };
      },
    });
    return cleanup;
  }, [
    themeAware,
    pixels,
    rate,
    r,
    g,
    b,
    br,
    bg,
    bb,
    reducedMotion,
    interactive,
    interactionRef,
    hoverStrength,
  ]);

  return (
    <div
      {...props}
      data-slot="dither-background"
      className={cn(
        "hangry-background relative isolate min-h-96 overflow-hidden border border-border",
        className,
      )}
    >
      <div aria-hidden="true" className="pointer-events-none absolute inset-0 -z-10">
        <div
          className={cn("absolute inset-0", themeAware && "hidden dark:block")}
          style={{ backgroundColor: `rgb(${br * 255} ${bg * 255} ${bb * 255})` }}
        >
          <div
            className="absolute inset-0"
            style={{
              backgroundImage: `radial-gradient(rgb(${r * 255} ${g * 255} ${b * 255}) 30%, transparent 31%)`,
              backgroundSize: `${pixels * 2}px ${pixels * 2}px`,
              maskImage: "radial-gradient(ellipse at center, black, transparent 80%)",
            }}
          />
        </div>
        {themeAware && (
          <div
            className="absolute inset-0 dark:hidden"
            style={{
              background: `radial-gradient(rgb(${r * 115} ${g * 115} ${b * 115}) 30%, #ebf5ef 31%) 0 0 / ${pixels * 2}px ${pixels * 2}px`,
            }}
          />
        )}
        <canvas ref={canvasRef} className="absolute inset-0 block h-full w-full opacity-0" />
      </div>
      {children}
    </div>
  );
});

import { lightInk, lightPaper } from "./light-palette.shared.wgsl";

struct Theme { mode: vec4f };
@group(1) @binding(0) var<uniform> theme: Theme;

struct Config {
  // Surface width, height, pixel size, and elapsed animation time.
  metrics: vec4f,
  // Normalized pointer position, hover strength, reserved.
  pointer: vec4f,
  // Click position, age in seconds, active flag.
  ripple: vec4f,
  foreground: vec4f,
  background: vec4f,
};
@group(0) @binding(0) var<uniform> cfg: Config;

@fragment fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
  let pixel = uv * cfg.metrics.xy;
  let hover = cfg.pointer.z;

  // Cursor lens. The push grows with distance from the pointer, so a cell can
  // move away from it but never past it (no mirrored or torn patch).
  let cursorDelta = pixel - cfg.pointer.xy * cfg.metrics.xy;
  let cursorDistance = length(cursorDelta);
  let cursorDir = cursorDelta / max(cursorDistance, 1.0);
  let cursorFalloff = max(0.0, 1.0 - cursorDistance / 120.0);
  let cursorPush = cursorDistance * 0.8 * cursorFalloff * cursorFalloff * hover;

  // Click ring. The push is capped so the first frames can't fold over the click point.
  let rippleDelta = pixel - cfg.ripple.xy * cfg.metrics.xy;
  let rippleDistance = length(rippleDelta);
  let rippleDir = rippleDelta / max(rippleDistance, 1.0);
  let ring = abs(rippleDistance - cfg.ripple.z * 225.0);
  let rippleForce = max(0.0, 1.0 - ring / 37.0) * max(0.0, 1.0 - cfg.ripple.z / 0.675) * 30.0 * cfg.ripple.w;
  let ripplePush = min(rippleForce, rippleDistance * 0.5);

  // Inverse-map the grid so its pixels move away from the pointer and click ring.
  let displaced = pixel - cursorDir * cursorPush - rippleDir * ripplePush;
  let grid = max(displaced, vec2f(0.0)) / cfg.metrics.z;
  let cell = floor(grid);
  let position = (cell + 0.5) * cfg.metrics.z / cfg.metrics.y;
  let center = cfg.metrics.xy / cfg.metrics.y * 0.5;
  let p = position - center;
  let time = cfg.metrics.w;
  let wave = sin(p.x * 5.0 + time) * cos(p.y * 4.0 - time * 0.7);
  let swirl = sin(length(p + vec2f(sin(time * 0.3) * 0.3, 0.0)) * 12.0 - time);
  let brightness = clamp(0.4 + wave * 0.25 + swirl * 0.2 - length(p) * 0.12, 0.0, 1.0);

  var bayer = array<f32, 16>(0.0, 8.0, 2.0, 10.0, 12.0, 4.0, 14.0, 6.0, 3.0, 11.0, 1.0, 9.0, 15.0, 7.0, 13.0, 5.0);
  let index = u32(cell.x) % 4u + (u32(cell.y) % 4u) * 4u;
  let threshold = (bayer[index] + 0.5) / 16.0;

  // Separate the displaced cells instead of letting them read as one solid patch.
  let spread = max(cursorFalloff * hover, min(1.0, rippleForce / 30.0));
  let gap = spread * 0.18;
  let withinCell = abs(fract(grid) - 0.5);
  let cellMask = 1.0 - step(0.5 - gap, max(withinCell.x, withinCell.y));

  // Clear space around the cursor so the pixels visibly move away from it.
  let cleared = step(22.0 * hover, cursorDistance);
  let ink = step(threshold, brightness) * cellMask * cleared;
  if (theme.mode.x > 0.5) {
    return vec4f(mix(lightPaper(), mix(lightInk(), cfg.foreground.rgb, 0.55), ink), 1.0);
  }
  return vec4f(mix(cfg.background.rgb, cfg.foreground.rgb, ink), 1.0);
}

import {
  effect,
  frame,
  frameLoop,
  init,
  sampler,
  surface,
  target,
  type Frame,
  type SurfaceOptions,
} from "vgpu";

type ShaderSource = Parameters<typeof effect>[1];
type Bindings = Parameters<ReturnType<typeof effect>["set"]>[0];

export interface PostProcessOptions {
  label: string;
  source: ShaderSource;
  uniforms?: (time: number, size: readonly [number, number]) => Bindings;
}

interface ShaderRendererOptions {
  label: string;
  uniforms: (time: number, size: readonly [number, number]) => Bindings;
  animated?: boolean;
  fps?: number;
  surface?: SurfaceOptions;
  postProcess?: PostProcessOptions;
  themeAware?: boolean;
  themeMask?: boolean;
}

/** Owns one canvas effect. Components supply bindings and retain their own input/UI logic. */
export function createShaderRenderer(
  canvas: HTMLCanvasElement,
  source: ShaderSource,
  {
    label,
    uniforms,
    animated = true,
    fps = 60,
    surface: surfaceOptions = { dpr: 1 },
    postProcess,
    themeAware = true,
    themeMask = false,
  }: ShaderRendererOptions,
) {
  let disposed = false;
  let gpu: Awaited<ReturnType<typeof init>> | undefined;
  let output: ReturnType<typeof surface> | undefined;
  let scene: ReturnType<typeof target> | undefined;
  let themeObserver: MutationObserver | undefined;
  let light = themeAware && !document.documentElement.classList.contains("dark");
  const theme = () => ({ mode: [Number(light), Number(themeMask), 0, 0] });
  let sceneSampler: ReturnType<typeof sampler> | undefined;
  let shader: ReturnType<typeof effect> | undefined;
  let postShader: ReturnType<typeof effect> | undefined;
  let loop: ReturnType<typeof frameLoop> | undefined;
  let observer: ResizeObserver | undefined;
  let unsubscribeResize: (() => void) | undefined;
  let pendingFrame = 0;
  let draw: ((currentFrame: Frame) => void) | undefined;
  canvas.style.opacity = "0";

  const dispose = () => {
    if (disposed) return;
    disposed = true;
    loop?.stop();
    observer?.disconnect();
    themeObserver?.disconnect();
    cancelAnimationFrame(pendingFrame);
    unsubscribeResize?.();
    shader?.dispose();
    postShader?.dispose();
    output?.dispose();
    gpu?.dispose();
  };
  const render = () => {
    if (disposed || !draw || animated) return;
    cancelAnimationFrame(pendingFrame);
    pendingFrame = requestAnimationFrame(() => {
      if (!disposed && gpu && draw) frame(gpu, draw);
    });
  };
  const start = async () => {
    const initialized = await init();
    if (disposed) {
      initialized.dispose();
      return;
    }
    gpu = initialized;
    output = surface(gpu, canvas, surfaceOptions);
    scene = postProcess ? target(gpu, { size: output.size }) : undefined;
    sceneSampler = postProcess
      ? sampler(gpu, { minFilter: "linear", magFilter: "linear" })
      : undefined;
    light = themeAware && !document.documentElement.classList.contains("dark");
    shader = effect(gpu, source, {
      label,
      set: { ...uniforms(0, (scene ?? output).size), theme: theme() },
    });
    postShader = postProcess
      ? effect(gpu, postProcess.source, {
          label: postProcess.label,
          set: {
            theme: theme(),
            scene: scene,
            sceneSampler,
            ...postProcess.uniforms?.(0, output.size),
          },
        })
      : undefined;
    await shader.compile(scene ?? output);
    await postShader?.compile(output);
    if (disposed) return;
    const startedAt = performance.now();
    if (output && scene && sceneSampler) {
      unsubscribeResize = output.onResize(({ width, height }) => {
        scene?.resize([width, height]);
        postShader?.set({
          scene,
          sceneSampler,
          ...postProcess?.uniforms?.(0, [width, height]),
        });
      });
    }
    draw = (currentFrame) => {
      if (!output || !shader || disposed) return;
      const time = animated ? (performance.now() - startedAt) / 1000 : 0;
      const renderTarget = scene ?? output;
      shader.set({ ...uniforms(time, renderTarget.size), theme: theme() });
      if (postShader && scene && sceneSampler) {
        postShader.set({
          theme: theme(),
          scene,
          sceneSampler,
          ...postProcess?.uniforms?.(time, output.size),
        });
        currentFrame.pass(scene, shader);
        currentFrame.pass(output, postShader);
      } else {
        currentFrame.pass(scene ?? output, shader);
      }
      canvas.style.opacity = "1";
    };
    if (themeAware) {
      themeObserver = new MutationObserver(() => {
        light = themeAware && !document.documentElement.classList.contains("dark");
        render();
      });
      themeObserver.observe(document.documentElement, {
        attributes: true,
        attributeFilter: ["class"],
      });
    }
    if (animated) loop = frameLoop(gpu, draw, { fps });
    else {
      observer = new ResizeObserver(render);
      observer.observe(canvas);
      render();
    }
  };
  void start().catch((error: unknown) => {
    if (!disposed) {
      canvas.style.opacity = "0";
      console.warn(`${label} could not start; retaining its fallback:`, error);
      dispose();
    }
  });
  return { dispose, render };
}

// Dedicated pigments for light-mode shader materials. No output filtering.
export fn lightPaper() -> vec3f { return vec3f(0.9568627, 0.9803922, 0.9647059); }
export fn lightSurface() -> vec3f { return vec3f(0.8470588, 0.9333333, 0.8862745); }
export fn lightInk() -> vec3f { return vec3f(0.0666667, 0.2352941, 0.1960784); }
export fn lightEmerald() -> vec3f { return vec3f(0.0000000, 0.4862745, 0.3450980); }
export fn lightCyan() -> vec3f { return vec3f(0.0000000, 0.5450980, 0.7215686); }
export fn lightBlue() -> vec3f { return vec3f(0.1568627, 0.3686275, 0.9098039); }
export fn lightViolet() -> vec3f { return vec3f(0.5098039, 0.2666667, 0.8470588); }
export fn lightRose() -> vec3f { return vec3f(0.8392157, 0.2352941, 0.5137255); }
export fn lightGold() -> vec3f { return vec3f(0.8431373, 0.5764706, 0.1137255); }
